import java.util.*;import com.koios.game.arpg.*;import com.koios.game.model.*;import com.koios.game.model.item.*;import com.koios.game.model.player.Player;import com.koios.GameService;
public final class ExactLootPickupCheck {
 static int checks;static void check(boolean b,String msg){checks++;if(!b)throw new AssertionError(msg);}
 static void pulse(int n){for(int i=0;i<n;i++)GameService.getTaskScheduler().pulse();}
 static String drop(Player p,Item item,Location at){int from=GroundLootMetadataCheck.mark(p);GroundItemManager.spawnPrivate(p,item,at);return GroundLootMetadataCheck.state(p,from).keySet().iterator().next();}
 static boolean owns(Player p,String uuid){for(int i=0;i<28;i++){Item item=p.getInventory().get(i);if(item!=null&&item.hasRoll()&&item.getRoll().getInstanceId().equals(uuid))return true;}return false;}
 public static void main(String[]args)throws Exception{PrototypeIntegrationCheck.loaded();Player p=PrototypeIntegrationCheck.player("exactloot",73),other=PrototypeIntegrationCheck.player("foreignloot",74);p.setAttribute("starter-claimed",true);p.setAttribute("tutorial-stage",11);p.setAttribute("intro-complete",true);MapRuns.home(p);PrototypeIntegrationCheck.idle(p);Location at=p.getLocation().copy();Item first=MapRuns.gem(1,false),second=MapRuns.gem(1,false);String one=drop(p,first,at),two=drop(p,second,at);GroundLootMetadata.handle(p,"arpgloot "+two);pulse(1);check(owns(p,second.getRoll().getInstanceId())&&!owns(p,first.getRoll().getInstanceId()),"Exact second label picks second UUID, never same-ID first entity");check(GameService.getGroundItemManager().getPlayerItems(p).stream().anyMatch(g->g.getItem().getRoll().getInstanceId().equals(first.getRoll().getInstanceId())),"First same-tile item remains on ground");int size=p.getInventory().size();GroundLootMetadata.handle(p,"arpgloot "+two);pulse(1);check(p.getInventory().size()==size,"Replayed stale key cannot duplicate inventory");
 for(int i=0;i<28;i++)p.getInventory().set(i,new Item(385));int failed=GroundLootMetadataCheck.mark(p);GroundLootMetadata.handle(p,"arpgloot "+one);pulse(1);check(GroundLootMetadataCheck.events(p,failed).isEmpty(),"Failed capacity pickup preserves label");p.getInventory().set(0,null);
 other.setPosition(at);PrototypeIntegrationCheck.idle(other);GroundLootMetadata.handle(other,"arpgloot "+one);pulse(1);check(other.getInventory().size()==0,"Other owner cannot resolve private key");
 p.setPosition(at.getX()+26,at.getY(),0);PrototypeIntegrationCheck.idle(p);GroundLootMetadata.handle(p,"arpgloot "+one);p.setPosition(at);PrototypeIntegrationCheck.idle(p);pulse(1);check(!owns(p,first.getRoll().getInstanceId()),"Over25tile request rejected before later arrival");
 p.setPosition(at.getX()+3,at.getY(),0);PrototypeIntegrationCheck.idle(p);GroundLootMetadata.handle(p,"arpgloot "+one);pulse(26);p.setPosition(at);PrototypeIntegrationCheck.idle(p);pulse(1);check(!owns(p,first.getRoll().getInstanceId())&&!p.walkingToItem,"Waiting request times out and cannot revive on arrival");
 for(int state=0;state<5;state++){GroundLootMetadata.handle(p,"arpgloot "+one);if(state==0)p.setDead(true);if(state==1)p.setIsTrading(true);if(state==2)p.getBankField().setBanking(true);if(state==3)p.setTeleporting(true);if(state==4)p.setBusy(true);pulse(1);p.setDead(false);p.setBusy(false);p.setIsTrading(false);p.getBankField().setBanking(false);PrototypeIntegrationCheck.idle(p);pulse(1);check(!owns(p,first.getRoll().getInstanceId()),"Busy state cancels pending pickup "+state);}
 GroundLootMetadata.handle(p,"arpgloot "+one);GroundLootMetadata.handle(p,"arpgloot bogus");pulse(1);check(!owns(p,first.getRoll().getInstanceId()),"New request cancels older request even if new key invalid");
 GroundLootMetadata.handle(p,"arpgloot "+one);p.getInventory().set(0,MapRuns.map(1,0,1));MapRuns.start(p,0,false);PrototypeIntegrationCheck.idle(p);pulse(1);check(!owns(p,first.getRoll().getInstanceId()),"Instance exit cancels pending ground pickup");MapRuns.home(p);PrototypeIntegrationCheck.idle(p);p.setPosition(at);PrototypeIntegrationCheck.idle(p);GroundLootMetadata.handle(p,"arpgloot "+one);pulse(1);check(owns(p,first.getRoll().getInstanceId()),"Fresh valid request after returning picks preserved original identity");MapRuns.cleanup(p);GroundLootMetadata.handle(p,"arpgloot "+one);pulse(1);check(!p.walkingToItem,"Cleanup invalidates old keys");System.out.println("Passed "+checks+" exact-label pickup checks.");}
}
